// R21 — the expression oracle testbench.
//
// Drives the combinational `ExprOracle` with vectors generated by
// `ExpressionOracleSuite`, and compares every output against the value the
// suite computed in Scala with `BigInt`. Nothing about the expected results is
// derived here: this program applies inputs and reports disagreement, so the
// oracle is the specification's arithmetic rather than a second C++ model of
// the same emitter.
//
// Vector file format, all values unsigned decimal:
//
//   line 1        the output port names, in column order
//   lines 2..N    a b amt, then one expected value per named output

#include "VExprOracle.h"
#include "verilated.h"

#include <cstdint>
#include <cstdio>
#include <fstream>
#include <functional>
#include <map>
#include <sstream>
#include <string>
#include <vector>

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);

  if (argc < 2) {
    printf("FAIL: no vector file given\n");
    return 1;
  }

  VExprOracle* dut = new VExprOracle;

  // Every output the oracle names, widened to 64 bits. Verilator gives a
  // 1-bit port as CData, a <=32-bit port as IData, and a <=64-bit port as
  // QData; an SInt port is an ordinary vector (R21.6: signedness is never
  // declared), so every comparison here is between raw bit patterns.
  const std::map<std::string, std::function<uint64_t()>> outputs = {
      {"sll", [&] { return (uint64_t)dut->sll; }},
      {"srl", [&] { return (uint64_t)dut->srl; }},
      {"sra", [&] { return (uint64_t)dut->sra; }},
      {"srlS", [&] { return (uint64_t)dut->srlS; }},

      {"ltu", [&] { return (uint64_t)dut->ltu; }},
      {"leu", [&] { return (uint64_t)dut->leu; }},
      {"gtu", [&] { return (uint64_t)dut->gtu; }},
      {"geu", [&] { return (uint64_t)dut->geu; }},
      {"lts", [&] { return (uint64_t)dut->lts; }},
      {"les", [&] { return (uint64_t)dut->les; }},
      {"gts", [&] { return (uint64_t)dut->gts; }},
      {"ges", [&] { return (uint64_t)dut->ges; }},

      {"mulu", [&] { return (uint64_t)dut->mulu; }},
      {"muls", [&] { return (uint64_t)dut->muls; }},
      {"mulh", [&] { return (uint64_t)dut->mulh; }},
      {"mulhu", [&] { return (uint64_t)dut->mulhu; }},
      {"mulhsu", [&] { return (uint64_t)dut->mulhsu; }},

      {"p1Bound", [&] { return (uint64_t)dut->p1Bound; }},
      {"p1Inline", [&] { return (uint64_t)dut->p1Inline; }},
      {"p2Bound", [&] { return (uint64_t)dut->p2Bound; }},
      {"p2Inline", [&] { return (uint64_t)dut->p2Inline; }},
      {"p3Bound", [&] { return (uint64_t)dut->p3Bound; }},
      {"p3Inline", [&] { return (uint64_t)dut->p3Inline; }},
      {"p4Bound", [&] { return (uint64_t)dut->p4Bound; }},
      {"p4Inline", [&] { return (uint64_t)dut->p4Inline; }},
      {"p5Bound", [&] { return (uint64_t)dut->p5Bound; }},
      {"p5Inline", [&] { return (uint64_t)dut->p5Inline; }},
      {"p6Bound", [&] { return (uint64_t)dut->p6Bound; }},
      {"p6Inline", [&] { return (uint64_t)dut->p6Inline; }},
      {"p7Bound", [&] { return (uint64_t)dut->p7Bound; }},
      {"p7Inline", [&] { return (uint64_t)dut->p7Inline; }},
      {"p8Bound", [&] { return (uint64_t)dut->p8Bound; }},
      {"p8Inline", [&] { return (uint64_t)dut->p8Inline; }},
  };

  std::ifstream in(argv[1]);
  if (!in) {
    printf("FAIL: cannot read %s\n", argv[1]);
    return 1;
  }

  std::string header;
  if (!std::getline(in, header)) {
    printf("FAIL: vector file has no header\n");
    return 1;
  }

  std::vector<std::string> names;
  {
    std::istringstream hs(header);
    std::string name;
    while (hs >> name) {
      if (outputs.find(name) == outputs.end()) {
        printf("FAIL: vector file names an output the testbench does not know: %s\n",
               name.c_str());
        return 1;
      }
      names.push_back(name);
    }
  }
  if (names.size() != outputs.size()) {
    printf("FAIL: vector file covers %zu of %zu outputs\n", names.size(), outputs.size());
    return 1;
  }

  long vectors = 0;
  long mismatches = 0;
  std::string line;
  while (std::getline(in, line)) {
    if (line.empty()) continue;
    std::istringstream ls(line);
    uint64_t a = 0, b = 0, amt = 0;
    ls >> a >> b >> amt;

    dut->a = (uint32_t)a;
    dut->b = (uint32_t)b;
    dut->amt = (uint8_t)amt;
    dut->eval();

    for (const std::string& name : names) {
      uint64_t expected = 0;
      ls >> expected;
      const uint64_t actual = outputs.at(name)();
      if (actual != expected) {
        if (mismatches < 10) {
          printf("MISMATCH %s: a=%llu b=%llu amt=%llu expected=%llu actual=%llu\n",
                 name.c_str(), (unsigned long long)a, (unsigned long long)b,
                 (unsigned long long)amt, (unsigned long long)expected,
                 (unsigned long long)actual);
        }
        mismatches++;
      }
    }
    vectors++;
  }

  delete dut;

  if (mismatches != 0) {
    printf("FAIL: %ld mismatches over %ld vectors\n", mismatches, vectors);
    return 1;
  }
  printf("PASS: %ld vectors x %zu outputs agree with the oracle\n", vectors, names.size());
  return 0;
}
